import {planarTargets,resolvePlanar} from './planar-rewards.js';
import {makeMonster} from './legends.js';
import {relicTargets,resolveRelic} from './legends.js';
import {facilityTargets,resolveFacility,priest} from './facilities.js';
import {ROOMS,UNITS} from './content.js';
import {GOOD_MAGIC,BAD_MAGIC,INVENTIONS} from './catalogue.js';
import {cell,roll,draw,table,root,group,event,gain,addUnit,makeRoom,connect,active,occupants,capacity,morale,threshold} from './model.js';
import {spawn,placement} from './discovery.js';
import {build,has,recruitReason,detach} from './construction.js';
import {kill,damageRoom} from './environment.js';
export function magic(s,good,id=null,origin='0,0'){const card=id==null?table(s):null;id??=card.rank+(good&&['♥','♦'].includes(card.suit)?13:0);const d=(good?GOOD_MAGIC:BAD_MAGIC)[id-1];if(!good){const temple=Object.values(s.rooms).find(r=>r.type==='temple'&&r.dedication==='pure'&&!r.storedCurse&&active(s,r)&&priest(s,r));if(temple){temple.storedCurse={id,origin};event(s,'Maldição aprisionada','O Templo da Pureza aprisionou '+d[0]+'. A maldição será liberada se o templo for danificado ou perder seu clérigo.',{art:'room:temple'});return;}}event(s,d[0],d[2],{tone:good?'good':'bad',art:'magic:'+(good?'good':'bad'),card,choice:{kind:'magic',good,id,origin}});}
export function targets(s,e){const c=e.choice;if(!c)return[];const planar=planarTargets(s,e);if(planar!==null)return planar;const relic=relicTargets(s,e);if(relic!==null)return relic;const facility=facilityTargets(s,e);if(facility!==null)return facility;if(c.kind==='magic'){const d=(c.good?GOOD_MAGIC:BAD_MAGIC)[c.id-1],target=d[1];if(!target)return[{value:'apply',label:'Resolver efeito'}];if(target==='unit')return s.units.filter(u=>u.team==='ally'&&u.hp>0).map(u=>({value:'u:'+u.id,label:u.name||UNITS[u.kind]?.name||u.kind}));if(target==='enemy')return s.units.filter(u=>u.team==='enemy'&&u.hp>0&&u.kind!=='immortal').map(u=>({value:'u:'+u.id,label:u.name||u.kind}));return Object.values(s.rooms).filter(r=>root(s,r)===r&&(target==='portal'?['portal','stabilizer'].includes(r.type):target==='housing'?capacity(s,r)>0:target==='built'?r.built:active(s,r)||r.id===c.origin)).map(r=>({value:r.id,label:ROOMS[r.type].name,x:r.x,y:r.y}));}
 if(['poison','map-labyrinth','feed','champion','sacrifice','witch','scout-companion'].includes(c.kind))return s.units.filter(u=>u.team==='ally'&&u.hp>0&&u.id!==c.exclude).map(u=>({value:'u:'+u.id,label:(u.name||UNITS[u.kind]?.name||u.kind)+' · '+Math.round(u.power)+' STR'})).concat(c.kind==='scout-companion'?[{value:'skip',label:'Ir sozinho'}]:[]);
 if(['project','copy','minor-artifact','scout'].includes(c.kind))return Object.values(s.rooms).filter(r=>active(s,r)&&(c.kind==='project'||c.kind==='copy'?r.type==='cave'&&!r.built:c.kind==='minor-artifact'?capacity(s,r)>0:true)).map(r=>({value:r.id,label:ROOMS[r.type].name,x:r.x,y:r.y}));
 if(c.kind==='ancient-prison')return[{value:'release',label:'Libertar'},{value:'leave',label:'Manter aprisionado'}];if(c.kind==='capture')return c.enemies.map((u,i)=>({value:String(i),label:`Capturar ${u.name||u.kind} · ${Math.round(u.power)} STR`})).concat({value:'skip',label:'Não capturar'});if(c.kind==='abandoned')return Object.entries(ROOMS).filter(([,d])=>d.r!==undefined&&!d.inventionOnly).map(([value,d])=>({value,label:d.name}));if(c.kind==='invention')return[{value:'apply',label:'Desenvolver invenção'}];return[];}
export function resolveChoice(s,e,value){const c=e.choice;if(!c)return;if(resolvePlanar(s,e,value)||resolveRelic(s,e,value)||resolveFacility(s,e,value,{magic}))return;if(value==='skip'&&['capture','scout-companion'].includes(c.kind))return;const unit=s.units.find(u=>'u:'+u.id===value),r=s.rooms[value]||s.rooms[c.room]||s.rooms[c.origin]||s.rooms['0,0'];
 if(c.kind==='magic'){applyMagic(s,c.good,c.id,r,unit);return;}if(c.kind==='poison')kill(s,unit,{instant:true});if(c.kind==='project'){build(s,c.type,value,null,{free:true});if(c.rewardTag==='factory')r.monsterFactory=true;if(c.rewardTag==='honey'){r.honey=true;addUnit(s,'insectqueen',r,'ally',20+Math.max(0,r.y),{loyal:true,fixed:true,size:2.6});}}if(c.kind==='copy')build(s,c.type,value,null,{free:true});if(c.kind==='minor-artifact'){r.artifact=(r.artifact||0)+15;for(const u of occupants(s,r)){u.power+=15;u.maxHp+=120;u.hp+=120;}event(s,'Artefato instalado','O abrigo escolhido recebeu +15 STR para seus ocupantes.',{tone:'good',art:'room:artifact'});}
 if(c.kind==='ancient-prison'&&value==='release'){r.released=true;if(roll(s,4)===4)addUnit(s,'beast',r,'ally',60,{loyal:true});else spawn(s,r,'beast',60,{boss:true});event(s,'Prisão antiga aberta','A criatura foi libertada.',{art:'room:ancientprison'});}
 if(c.kind==='abandoned'){r.type=value;r.built=true;r.damaged=true;event(s,'Construção abandonada',ROOMS[value].name+' foi encontrada danificada.',{art:'room:'+value});}
 if(c.kind==='map-labyrinth'){if(roll(s,4)===4){root(s,r).mapped=true;event(s,'Labirinto mapeado','Toda a área do labirinto está transitável.',{tone:'good',art:'room:labyrinth'});}else{kill(s,unit,{instant:true});event(s,'Perdido no labirinto','O explorador não voltou. A área continua bloqueada.',{tone:'bad',art:'room:labyrinth'});}}
 if(c.kind==='feed'){kill(s,unit,{instant:true});const u=s.units.find(u=>u.id===group(s,r).guard);u.power+=20;u.maxHp=u.hp=u.power*8;event(s,'Criatura alimentada','O sacrifício aumentou a força da criatura em 20 STR.',{art:'room:hungry'});}
 if(c.kind==='champion'){const u=s.units.find(u=>u.id===group(s,r).guard);if(roll(s,4)===4){u.team='ally';u.loyal=false;u.mutiny=8;group(s,r).guard=null;event(s,'Campeão conquistado','O campeão de 60 STR juntou-se à fortaleza.',{tone:'good',art:'room:challenge'});}else{kill(s,unit,{instant:true});u.team='enemy';event(s,'Desafio perdido','O desafiante morreu e o campeão está atacando.',{tone:'bad',art:'room:challenge'});}}
 if(c.kind==='capture'){const prison=Object.values(s.rooms).find(p=>['solitary','prison'].includes(p.type)&&!p.prisoner&&active(s,p));if(prison){prison.prisoner={...c.enemies[Number(value)]};for(const edge of Object.values(s.edges))if(edge.a===prison.id||edge.b===prison.id)edge.bars={hp:200,maxHp:200,cell:prison.id};event(s,'Prisioneiro capturado','O inimigo foi levado à prisão. Grades fecham suas passagens.',{art:'room:prison'});}}
 if(c.kind==='scout'){const u=s.units.find(u=>u.id===c.unit);u.x=r.x;u.y=r.y;u.move=null;event(s,'Companheiro do Batedor','Escolha um aliado para acompanhar o Batedor.',{art:'room:tavern',choice:{kind:'scout-companion',exclude:u.id,room:r.id}});}if(c.kind==='scout-companion'&&unit){unit.x=r.x;unit.y=r.y;unit.move=null;}
 if(c.kind==='witch'){if(roll(s,2)===1){unit.fixed=true;unit.witchFixed=true;event(s,'Imobilizado pela Bruxa','A unidade não poderá se mover neste combate.',{art:'magic:bad'});}else{unit.witchPower=unit.power;unit.power*=2;unit.maxHp=unit.hp=unit.power*8;event(s,'Força da Bruxa','A unidade terá força dobrada neste combate.',{art:'magic:good'});}}
 if(c.kind==='sacrifice'){if(r.usedDay===s.day)throw Error('Uma oferenda por dia.');r.usedDay=s.day;kill(s,unit,{instant:true});s.morale-=5;magic(s,true,null,r.id);if(unit.godTouched)magic(s,true,null,r.id);}
 if(c.kind==='invention')applyInvention(s,c.id,r);
}
export function applyMagic(s,good,id,r,u){const f=s.flags;if(good){switch(id){case 1:{const c=table(s),y=Math.min(30,r.y+c.rank);if(y===r.y){event(s,'Passagem sem destino','Não há profundidade disponível para o segundo portal.',{art:'magic:good'});break;}const end=s.rooms[cell(r.x,y)]||makeRoom(s,r.x,y,'cave');r.teleport=end.id;end.teleport=r.id;event(s,'Passagem Profunda aberta','Um par de passagens liga as duas salas. Não são portais de invasão planar.',{tone:'good',art:'room:portal'});break;}case 2:r.trap={kind:'damage',level:3,armed:true,passable:true};break;case 3:f.livingMetal=(f.livingMetal||0)+1;break;case 4:{const v=addUnit(s,u.kind,u.home,'ally',u.power,{loyal:true,range:u.range,size:u.size});v.x=u.x;v.y=u.y;break;}case 5:r.catPortal=true;break;case 6:r.fleetForest=true;break;case 7:r.type='cave';r.source=null;break;case 8:r.siren=true;break;case 9:r.healing=true;break;case 10:f.gills=true;break;case 11:f.hospitalGlobal=true;break;case 12:r.chains=true;break;case 13:f.charms=(f.charms||0)+1;break;case 14:detach(s,r);group(s,r).type='portal';r.type='portal';r.planarRealm=roll(s,13)-1;r.portalDay=s.day;break;case 15:f.euphoria=(f.euphoria||0)+1;break;case 16:r.ice=true;r.source&&(r.source.solid=true);r.fluid=null;break;case 17:for(const p of Object.values(s.rooms).filter(p=>p.prisoner)){const h=Object.values(s.rooms).find(h=>active(s,h)&&capacity(s,h)>occupants(s,h).length&&morale(s)>=threshold(s,{kind:p.prisoner.kind,home:h.id,mutiny:12},h));if(h){addUnit(s,p.prisoner.kind,h,'ally',p.prisoner.power,{loyal:false,mutiny:12});p.prisoner=null;}}break;case 18:r.type='mansion';r.built=true;break;case 19:f.ratPower=(f.ratPower||0)+2;for(const v of s.units.filter(v=>v.kind==='rat'&&v.team==='ally')){v.power+=2;v.maxHp+=16;v.hp+=16;}break;case 20:event(s,'Destino da cópia','Escolha uma caverna livre para a cópia gratuita.',{art:'room:'+r.type,choice:{kind:'copy',type:r.type}});break;case 21:u.godTouched=true;break;case 22:f.autoTraps=true;break;case 23:f.watching=true;break;case 24:addUnit(s,'hero','0,0','ally',75,{name:'Herói Devoto',loyal:false,mutiny:16});break;case 25:addUnit(s,'golem',r,'ally',100,{name:'Sala Viva',loyal:false,mutiny:5,size:2.6});r.type='cave';r.built=false;break;case 26:r.summoning=true;break;}}
 else switch(id){case 1:{const cells=group(s,r).cells;gain(s,0,30*cells.length,'Toque do Rei Ganancioso','A construção se transformou em riquezas.',{art:'magic:bad'});for(const key of cells){s.rooms[key].type='cave';s.rooms[key].built=false;}break;}case 2:f.doubleBuild=true;break;case 3:f.diamondDust=true;break;case 4:kill(s,u,{instant:true});break;case 5:{const n=roll(s,4)+roll(s,4);let previous=r;for(let i=0;i<n&&r.y+i<=30;i++){const p=s.rooms[cell(r.x,r.y+i)]||makeRoom(s,r.x,r.y+i,'cave');damageRoom(s,p,magic);p.fluid='lava';if(i)connect(s,previous,p);previous=p;}break;}case 6:r.type='portal';r.chaos=true;r.portalDay=s.day;break;case 7:{const [dx,dy]=[[0,-1],[1,0],[0,1],[-1,0]][roll(s,4)-1],n=roll(s,4);let previous=r;for(let i=1;i<=n;i++){const x=r.x+dx*i,y=r.y+dy*i;if(y<0||y>30||Math.abs(x)>20)break;const p=s.rooms[cell(x,y)]||makeRoom(s,x,y,'cave');damageRoom(s,p,magic);connect(s,previous,p);previous=p;}break;}case 8:r.swampDay=s.day+1;break;case 9:spawn(s,r,'troll',100,{boss:true});s.units.at(-1).speed=0;break;case 10:f.jokerDays??={};f.jokerDays.red=s.day+5;makeMonster(s,r,100,3,{magic});break;case 11:u.team='enemy';break;case 12:for(const v of s.units.filter(v=>v.team==='ally'&&!['golem','siege','undead'].includes(v.kind)&&Math.abs(v.x-u.x)<=2&&Math.abs(v.y-u.y)<=2)){v.kind='undead';v.team='enemy';v.power=10;v.hp=v.maxHp=80;}break;case 13:makeMonster(s,r,25,1,{magic});break;}
}
export function applyInvention(s,id,r){if(s.knownInventions.includes(id)){event(s,'Invenção conhecida','Este projeto já foi desenvolvido.',{art:'room:artificer'});return;}s.knownInventions.push(id);if(id===1)spawn(s,r,'guardian',200,{boss:true});if(id===3){s.flags.brewery=true;for(const u of s.units.filter(u=>u.hero)){u.power*=2;u.hp=u.maxHp=u.power*8;}}if(id===5)for(const p of Object.values(s.rooms))if(p.source?.kind==='lava'){p.source.solid=true;p.fluid=null;}if(id===10)for(const u of s.units.filter(u=>u.team==='ally'&&['archer','siege'].includes(u.kind))){const n=u.kind==='siege'?20:5;u.power+=n;u.hp=u.maxHp=u.power*8;}const type={2:'concert',3:'brewery',6:'orefinder',10:'dragonforge',12:'trapmaster',13:'endersgate'}[id];if(type)event(s,'Instalar '+ROOMS[type].name,'Escolha uma caverna para a nova invenção.',{art:'room:'+type,choice:{kind:'project',type}});}
